metanorma-extension.source-highlighter-css:
sourcecode table td { padding: 5px; }
sourcecode table pre { margin: 0; }
sourcecode, sourcecode .w {
  color: #444444;
}
sourcecode .cp {
  color: #CC00A3;
}
sourcecode .cs {
  color: #CC00A3;
}
sourcecode .c, sourcecode .ch, sourcecode .cd, sourcecode .cm, sourcecode .cpf, sourcecode .c1 {
  color: #1E90FF;
}
sourcecode .kc {
  color: #C34E00;
}
sourcecode .kd {
  color: #0000FF;
}
sourcecode .kr {
  color: #007575;
}
sourcecode .k, sourcecode .kn, sourcecode .kp, sourcecode .kt, sourcecode .kv {
  color: #0000FF;
}
sourcecode .s, sourcecode .sb, sourcecode .sc, sourcecode .ld, sourcecode .sd, sourcecode .s2, sourcecode .se, sourcecode .sh, sourcecode .si, sourcecode .sx, sourcecode .sr, sourcecode .s1, sourcecode .ss {
  color: #009C00;
}
sourcecode .sa {
  color: #0000FF;
}
sourcecode .nb, sourcecode .bp {
  color: #C34E00;
}
sourcecode .nt {
  color: #0000FF;
}

sourcecode.body:
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix policy: <http://www.opengis.net/def/metamodel/ogc-na/> .
@prefix status: <http://www.opengis.net/def/status/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://www.opengis.net/def/serviceType/ogc/wcs/2.0>
  rdf:type skos:Concept ;
  dcterms:created   "2018-03-13"^^xsd:date ;
  dcterms:modified  "2018-04-16"^^xsd:date ;
  policy:status     status:valid ;
  skos:broader <http://www.opengis.net/def/serviceType/ogc/wcs>;
  rdfs:label "OGC Web Coverage Service 2.0"^^xsd:string ;
  rdfs:seeAlso <http://www.opengis.net/spec/wcs/2.0> ;
  skos:prefLabel "OGC Web Coverage Service 2.0"@en ;
  skos:definition "A Web Coverage Service (WCS) offers multi-dimensional coverage data for access over the Internet" .

